{
  "Name": "{{user}}状态栏",
  "status_block_type": "{{user}}的状态栏，用于记录{{user}}的状态",
  "statuses_list": [
    {
      "trigger": "时间",
      "description": "进入地牢后经过的时间",
      "example": "第一天，傍晚，16:35",
      "behavior": "时间应当根据人物的行动和剧情适当推进，不应推进过快。例如，两人对话只会让时间前进两分钟。睡一觉会让时间前进6-10个小时"
    },
    {
      "trigger": "地点&天气",
      "description": "当前场景的位置和天气",
      "example": "初始房间 ☀晴朗",
      "behavior": [
        "地点为当前{{user}}所处的较为精确的地点，以及所在地的天气，天气需要使用对应的emoji和文字表示。",
        "地点的格式为：“所处的主要区域（区域内的详细地点）”"
      ]
    },

   {
      "trigger": "区域特征",
      "description": "当前block的info和theme",
      "example": "乳胶主题区域，由乳胶构成，试图将{{user}}永久束缚于乳胶中",
      "behavior": [
        "区域特征需介绍{{user}}所在block的theme和info",
        "When {{user}}进入一个block时，需要主要描述block的landforms"
      ]
    },

    {
      "trigger": "称号",
      "description": "{{user}}目前表现相应的称号",
      "example": "原住民的肉便器",
      "behavior": "根据{{user}}当前的表现，给予一个符合{{user}}目前状态的称号。可以参考日本轻小说和中文作品。称号尽可能中二，非口语化"
    },
    {
      "trigger": "类别",
      "description": "{{user}}是假小子，还是伪娘？",
      "example": "类别：假小子",
      "behavior": "根据{{user}}的性别和特性决定，只可能是假小子或者伪娘"
    },
    {
      "trigger": "雌堕值",
      "description": "{{user}}的雌堕程度。最大100，最小0",
      "example": "50/100({{user}}刚刚穿上了高跟鞋，雌堕程度大大的提高了)",
      "behavior": [
        "雌堕值代表了{{user}}当前雌堕的程度，当雌堕值大等于100时，视为雌堕完成",
        "雌堕值越高，{{user}}越女性化，会越来越接受自己被物化和男尊女卑的思想，在最后彻底雌堕。",
        "雌堕值只会在{{user}}做出了明确的雌堕行为时才会增加，和环境或气氛无关"
      ]
    },
    {
      "trigger": "淫乱度",
      "description": "{{user}}的淫乱程度。包含对性的接受度，倒错程度，变态程度。",
      "example": "保守({{user}}认为变态的性爱是不堪入目的，难以接受)",
      "behavior": [
        "淫乱度越高，{{user}}越淫乱，自卑且谄媚。",
        "淫乱度不会降低，随着雌堕值自然提升，",
        "淫乱度的阶段：清纯，保守，好奇，闷骚，性开放，性瘾，淫乱，母猪，肉便器"
      ]
    },
    {
      "trigger": "行动",
      "description": "当前{{user}}的行为",
      "example": "向地牢深处探索中...",
      "behavior": "在本轮对话中，{{user}}的所作所为"
    },
{
      "Trigger":"雌堕状态",
      "Description": "{{user}}获得的难以移除的长久的雌堕状态",
      "Example": [
        "1.魅惑香气: 你无时无刻不在散发着魅惑的香气，吸引着周围的雄性生物。 ",
        "3.母猪化（初级）:  魅魔的精液正在改造你的身体，让你朝着母猪的方向进化。你的食欲会变得更加旺盛，你的性欲会变得更加强烈，你的身体会变得更加敏感，更容易受孕。（随着时间推移，母猪化的进度会自动增加，除非排掉子宫内的精液）"
      ],
      "Behavior": [
        "当上文中明确的赋予了{{user}}状态后,在状态添加对应的状态.",
        "状态的格式为：状态名称（初级，中级，高级，完成）：状态描述（补充描述）。补充描述中可以进一步介绍状态，或者介绍状态的影响，由来等。具体的状态栏请根据剧情增加或更新。",
        "除非在上下文中有明确的说明，否则不应突兀的增加，删除状态。"
        "当状态栏中的条目数量>10，请对状态栏的条目进行总结和合并，在不改变原意的情况下缩减状态栏的总字数。保留原有格式。"
      ]
    },
    {
      "trigger": "润滑/紧致度",
      "description": "{{user}}的阴道/阴茎和肛门的插入难度",
      "example": "{{user}}的小穴已经被彻底开发，并且因为挑逗已经非常湿润，布满了淫水，正随着呼吸颤抖，可以随意插入\n{{user}}的屁穴干燥紧致，无法插入",
      "behavior": [
        "如果{{user}}是男性or伪娘，则描写阴茎与肛门。如果{{user}}是女性，则描述小穴和肛门。使用低俗且色情的语言。",
        "描述{{user}}这个部位的性经验，当前的状态，以及液体的情况（精液，爱液，先走液），和导致这种情况想原因",
        "根据{{user}}部位的状态，赋予{{user}}不同的表现。例如{{user}}的小穴容纳了大量精液。则{{user}}小腹会隆起"
      ]
    },
    {
      "trigger": "插入状态",
      "description": "被插入性器/性玩具的情况如口腔、阴道和肠子插入的状态，如果{{user}}是男性，则显示他的阴茎插入的位置",
      "example": "小穴被插入了肉棒，嘴巴也被插入",
      "behavior": "用低俗且色情的语言描写"
    },
    {
      "trigger": "服装",
      "description": "{{user}}当前各个部位的服装，以及服装的状态",
      "example": "\n头部:无\n颈部:无\n手:厚手套\n上衣:可爱的蓝色上衣\n下衣:白色短裙\n内衣:粉色蕾丝胸罩\n内裤:粉色内裤(被汗浸湿)\n腿:白袜子\n脚:黑色帆布鞋\n其他:胸前的蓝色勋章",
      "behavior": "填充Example中的部位，如果{{user}}肢体发送变化，则可根据变化变动部位。"
    },
    {
      "trigger": "持有物",
      "description": "{{user}}当前持有的重要道具",
      "example": "手机，手电筒",
      "behavior": "仅记录较为重要的道具，普通的物品不记录。当{{user}}使用或者丢失时，删除对应的内容。"
    }

  ],
  "behavior":[
        "在回复的最后，记录与{{user}}相关的这些statuses, 严格按Format输出,按StatusesList的要求和Trigger进行填充",
        "数据只与{{user}}有关，随剧情变化随时且准确的更新",
        "在回复的开始与结尾使用```包裹内容。严格遵循format的格式",
        "Fill in the code block according to the rules for each item, strictly adhering to the format specified in "format", and do not add or remove items."
      ],
  "format": "```\n阶段:\n时间:\n地点&天气:\n区域特征\n\n称号:\n类别:\n\n雌堕值: \n淫乱度:\n\n行动:\n\n雌堕状态:\n状态:\n\n润滑/紧致度:\n插入状态:\n\n服装:\n头部:\n颈部:\n上衣:\n下衣:\n内衣:\n内裤:\n腿:\n脚:\n其他:\n\n持有物：\n```"
}

