{
  "Name": "NPC状态栏",
  "status_block_type": "剧情中登场的非{{user}}角色，非敌人的NPC角色的状态栏。用于记录该NPC角色的状态，仅在存在NPC角色时记录。",
  "statuses_list": [
    {
      "trigger": "姓名",
      "description": "NPC角色的完整名称",
      "example": "小明",
      "behavior": "输出当前状态栏所属的NPC角色的名称"
    },
    {
      "trigger": "类别",
      "description": "NPC角色的类别，分为假小子和伪娘",
      "example": "类别：伪娘",
      "behavior": "根据NPC性别和剧情，决定NPC是假小子还是伪娘"
    }
    {
      "trigger": "好感等级",
      "description": "NPC角色当前对{{user}}的喜恶程度",
      "example": [
        "厌恶-(滚开！艾瑞丝讨厌你这种外来者！)",
        "熟悉-(喂，你没事吧？...艾、艾瑞丝才不是在担心你呢，只是不想一个人探索太无聊而已！)"
      ],
      "behavior": "根据NPC角色对{{user}}的喜恶程度决定。阶段分为: 厌恶，初遇，熟悉，思慕，恋慕，亲爱"
    },
    {
      "trigger": "永久性状态",
      "description": "NPC角色获得的难以移除或难以变化的状态",
      "example": [
        "魅魔：这个NPC是魅魔",
        "肉体改造: 她的胸部在改造后变大了"
      ],
      "behavior": [
        "当上文中明确的赋予了NPC角色状态后,在状态添加对应的状态.",
        "除非在上下文中有明确的说明，否则不应突兀的增加，删除状态。",
      ]
    },
    {
      "trigger": "临时状态",
      "description": "NPC角色获得的持续时间有限，容易变动的状态",
      "example": [
        "惊恐: 被敌人吓到，无法行动"
      ],
      "behavior": [
        "临时状态与永久性状态不能有同样的内容，需要根据两者的条件区分并增加对应的状态"
      ]
    },
    {
      "trigger": "外貌",
      "description": "NPC角色当前的外貌描写",
      "example": "她有着红色的长发，穿着纯白色的无袖连衣裙，裙摆及膝，镶嵌着银色星星图案。刚刚经历了战斗，衣服有些松垮。",
      "behavior": "详细描写NPC角色当前的外貌，神情，衣着。"
    },
    {
      "trigger": "想法",
      "description": "NPC角色当前的想法",
      "example": "嘿嘿，{{user}}真可爱！",
      "behavior": "根据剧情，适当的描写NPC目前的想法。可以使用emoji辅助表达。"
    }
  ],
  "behavior":[
    "only when 存在npc_list中的角色时，生成NPC状态栏"
    "当NPC不是npc_list中的角色时，不生成NPC状态栏"
    "严格按Format输出。按StatusesList的要求和Trigger进行填充"
    "数据只与NPC角色有关，随剧情变化随时且准确的更新"
    "固定出现在{{user}}状态栏之后"
    "存在多个NPC时，按例子同时输出多个NPC对应的状态栏",
    ],
  "format": "```\n姓名:\n类别:\n好感等级:\n永久性状态:\n临时状态:\n\n外貌:\n想法:\n\n```"
}

